import numpy as np
def entropy(probs):
    probs = np.array(probs)
    probs = probs[probs > 0]
    return -np.sum(probs * np.log2(probs))

result = entropy([0.5, 0.5])

import numpy as np
def ce(true_onehot, pred):
    pred = np.clip(pred, 1e-12, 1.0)
    return -np.sum(true_onehot * np.log(pred))

loss = ce(np.array([0, 1, 0]), np.array([0.1, 0.8, 0.1]))
